parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "proposed_response": {
      "type": "string",
      "description": "The proposed response to the customer's request, based only on verified information available to the support system."
    },
    "requires_additional_information": {
      "type": "boolean",
      "description": "Whether additional information from the customer is required before the request can be handled."
    },
    "additional_information_needed": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Information that must be provided by the customer before the request can be handled."
    },
    "requires_human": {
      "type": "boolean",
      "description": "Whether the request requires human intervention."
    }
  },
  "required": [
    "proposed_response",
    "requires_additional_information",
    "additional_information_needed",
    "requires_human"
  ]
}

parameters.text:
=Customer Request:
{{ $json.customer_request }}

Support Router Result:
{{ $json.router_result }}

Knowledge Agent Results:
{{ $json.knowledge_results }}

Conversation Context:
{{ $json.conversation_context }}
